package io.github.reiko45.galacticraft.registry;

import io.github.reiko45.galacticraft.GalacticraftCore;
import io.github.reiko45.galacticraft.world.OilPocketFeature;
import java.util.function.Supplier;
import net.minecraft.core.registries.Registries;
import net.minecraft.world.level.levelgen.feature.Feature;
import net.minecraft.world.level.levelgen.feature.configurations.NoneFeatureConfiguration;
import net.neoforged.neoforge.registries.DeferredRegister;

/** Worldgen feature types; their configured/placed instances are generated by GCWorldgenProvider. */
public final class GCFeatures {
    public static final DeferredRegister<Feature<?>> FEATURES = DeferredRegister.create(Registries.FEATURE, GalacticraftCore.MOD_ID);

    public static final Supplier<OilPocketFeature> OIL_POCKET = FEATURES.register("oil_pocket",
            () -> new OilPocketFeature(NoneFeatureConfiguration.CODEC));
    public static final Supplier<io.github.reiko45.galacticraft.world.SlimelingEggFeature> SLIMELING_EGGS = FEATURES.register("slimeling_eggs",
            () -> new io.github.reiko45.galacticraft.world.SlimelingEggFeature(NoneFeatureConfiguration.CODEC));

    public static final Supplier<io.github.reiko45.galacticraft.world.VenusFeature> VENUS = FEATURES.register("venus",
            () -> new io.github.reiko45.galacticraft.world.VenusFeature(NoneFeatureConfiguration.CODEC));

    private GCFeatures() {
    }
}
